package com.company;

import java.util.*;

public class Combinations {
    public List<List<Integer>> combine(int n, int k) {
        List<List<Integer>> combinations = new ArrayList<>();
        combineHelper(n, k, new ArrayList<>(), combinations, 1);
        return combinations;
    }

    private void combineHelper(int n, int k, List<Integer> currentCombination, List<List<Integer>> combinations, int startIndex) {
        if (currentCombination.size() == k) {
            combinations.add(new ArrayList<>(currentCombination));
            return;
        }

        for (int i = startIndex; i <= n - (k - currentCombination.size()) + 1; i++) {
            currentCombination.add(i);
            combineHelper(n, k, currentCombination, combinations, i + 1);
            currentCombination.remove(currentCombination.size() - 1);
        }
    }
}
