        int current = queue.poll();
        // Check if the current n-tersection is the ending n-tersection
        if (current == end[0]) {
            // If the current n-tersection is the ending n-tersection, return "can be travelled"
            return "can be travelled";
        }
        // Loop through the paths between adjacent n-tersections
        for (int[] path : paths) {
            // Check if the current n-tersection is one of the paths
            if (current == path[0]) {
                // If the current n-tersection is one of the paths, add the adjacent n-tersection to the queue
                queue.offer(path[1]);
                // Mark the adjacent n-tersection as visited
                visited[path[1]] = true;
            }
        }
    }
    // If the queue is empty and the ending n-tersection is not visited, return "cannot be travelled"
    return "cannot be travelled";
}
