    return dfs(visited, start, end, paths);
}

private static boolean dfs(boolean[] visited, int[] current, int[] end, int[][] paths) {
    if (current[0] == end[0] && current[1] == end[1]) {
        return true;
    }
    for (int[] path : paths) {
        int nextX = path[0];
        int nextY = path[1];
        if (nextX == current[0] || nextY == current[1]) {
            visited[nextX] = true;
            if (dfs(visited, nextX, nextY, paths)) {
                return true;
            }
            visited[nextX] = false;
        }
    }
    return false;
}
