public static int[] diagonalOrder(int[][] mat) {
    int m = mat.length;
    int n = mat[0].length;
    int[] result = new int[m * n];
    int index = 0;

    for (int i = 0; i < m + n - 1; i++) {
        int startRow = Math.max(0, i - n + 1);
        int startCol = Math.max(0, n - i - 1);
        int endRow = Math.min(m - 1, i);
        int endCol = Math.min(n - 1, i);

        if (endRow - startRow > endCol - startCol) {
            for (int j = startRow; j <= endRow; j++) {
                result[index++] = mat[j][i - j + startCol];
            }
        } else {
            for (int j = startCol; j <= endCol; j++) {
                result[index++] = mat[i - j + startRow][j];
            }
        }
    }

    return result;
}
